"""Shared helpers for reading the plain text data files."""

import datetime
import re

# Separators and trimming only ever involve spaces and tabs.
BLANKS = " \t"

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_FIELD_SPLIT_RE = re.compile(r"[ \t]+")


class ParseError(ValueError):
    """A line in a data file breaks the rules.

    ``.line`` is the line number (counting from 1, blank and comment lines
    included); the message always mentions ``line N``.
    """

    def __init__(self, line, message):
        self.line = line
        self.reason = message
        super().__init__("line %d: %s" % (line, message))


def content_lines(text):
    """Yield ``(number, line)`` for each line that is not blank or a comment.

    A leading byte order mark is ignored, and a line ends at LF or CRLF only.
    """
    if text.startswith("﻿"):
        text = text[1:]
    for index, line in enumerate(text.split("\n")):
        if line.endswith("\r"):
            line = line[:-1]
        stripped = line.strip(BLANKS)
        if not stripped or stripped.startswith("#"):
            continue
        yield index + 1, line


def split_fields(line, maxsplit=0):
    """Split a line on runs of spaces/tabs, ignoring blanks at both ends."""
    return _FIELD_SPLIT_RE.split(line.strip(BLANKS), maxsplit=maxsplit)


def parse_date(value):
    """Return a ``datetime.date`` for ``YYYY-MM-DD``, or ``None`` if invalid."""
    if not _DATE_RE.fullmatch(value):
        return None
    try:
        return datetime.date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        return None


def is_sku(value):
    return _SKU_RE.fullmatch(value) is not None

