"""The shelves: the catalogue, stock movements and what is low."""

import re
from dataclasses import dataclass, field
from datetime import date as _date
from decimal import Decimal

from ._text import BLANKS, ParseError, content_lines, is_sku, parse_date, split_fields

TAX_RATES = {"standard": 20, "reduced": 5, "zero": 0}  # percent

_PRICE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
_COUNT_RE = re.compile(r"[0-9]+")
_QUANTITY_RE = re.compile(r"[+-]?[0-9]+")


@dataclass
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"
    line: int = field(default=0, compare=False, repr=False)

    @property
    def price_pennies(self):
        return int(self.price * 100)


@dataclass
class Movement:
    date: _date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False, repr=False)


def parse_price(value):
    """Return a price as a two-place ``Decimal``, or ``None`` if invalid."""
    if not _PRICE_RE.fullmatch(value):
        return None
    price = Decimal(value).quantize(Decimal("0.01"))
    if price < Decimal("0.01"):
        return None
    return price


def parse_catalog(text):
    """Parse ``catalog.txt``; return a dict of upper-case SKU to `Product`."""
    catalog = {}
    for number, line in content_lines(text):
        fields = [f.strip(BLANKS) for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                number,
                "expected 4 or 5 fields separated by '|', found %d" % len(fields),
            )
        sku, name, price_text, reorder_text = fields[:4]
        if not is_sku(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(
                number,
                "SKU %s is already on line %d" % (sku, catalog[sku].line),
            )
        if not name:
            raise ParseError(number, "the name is empty")
        price = parse_price(price_text)
        if price is None:
            raise ParseError(number, "bad price %r" % price_text)
        if not _COUNT_RE.fullmatch(reorder_text):
            raise ParseError(number, "bad reorder level %r" % reorder_text)
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(
                    number,
                    "bad tax band %r (standard, reduced or zero)" % fields[4],
                )
        catalog[sku] = Product(sku, name, price, int(reorder_text), tax, number)
    return catalog


def parse_quantity(value):
    """A signed, non-zero whole number, or ``None``."""
    if not _QUANTITY_RE.fullmatch(value):
        return None
    quantity = int(value)
    return quantity if quantity != 0 else None


def counting_order(movements):
    """The movements in the order they count: by date, then file order."""
    return sorted(movements, key=lambda m: m.date)


def first_negative(movements):
    """Return ``(movement, balance)`` for the first movement (in counting
    order) that takes a stock below zero, or ``None``."""
    balances = {}
    for move in counting_order(movements):
        balance = balances.get(move.sku, 0) + move.quantity
        balances[move.sku] = balance
        if balance < 0:
            return move, balance
    return None


def parse_movements(text, catalog):
    """Parse ``movements.txt``; return the movements in file order."""
    movements = []
    for number, line in content_lines(text):
        parts = split_fields(line, maxsplit=3)
        if len(parts) < 3:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku, quantity_text = parts[:3]
        note = parts[3] if len(parts) > 3 else ""
        when = parse_date(date_text)
        if when is None:
            raise ParseError(number, "bad date %r" % date_text)
        if sku.upper() not in catalog:
            raise ParseError(number, "SKU %r is not in the catalogue" % sku)
        quantity = parse_quantity(quantity_text)
        if quantity is None:
            raise ParseError(number, "bad quantity %r" % quantity_text)
        movements.append(Movement(when, sku.upper(), quantity, note, number))
    problem = first_negative(movements)
    if problem is not None:
        move, balance = problem
        raise ParseError(
            move.line,
            "stock of %s goes below zero (%d) on %s"
            % (move.sku, balance, move.date.isoformat()),
        )
    return movements


def stock_levels(catalog, movements):
    """A dict of SKU to quantity on the shelf, for every catalogue product."""
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        levels[move.sku] = levels.get(move.sku, 0) + move.quantity
    return levels


def stock_status(onhand, reorder):
    if onhand <= 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def to_buy(onhand, reorder):
    return max(1, 2 * reorder - onhand)


def history(movements, sku):
    """``(movement, balance)`` pairs for one SKU, in counting order."""
    sku = sku.upper()
    balance = 0
    rows = []
    for move in counting_order(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def format_delta(quantity):
    return "%+d" % quantity


def format_movement(move):
    """A movement as written in ``movements.txt``."""
    text = "%s %s %s" % (move.date.isoformat(), move.sku, format_delta(move.quantity))
    if move.note:
        text += " " + move.note
    return text

