"""The orders: parsing, pricing, what has shipped and what can ship."""

import re
from dataclasses import dataclass, field
from datetime import date as _date
from decimal import Decimal
from typing import List, Tuple

from ._text import ParseError, content_lines, is_sku, parse_date, split_fields
from .shelves import TAX_RATES, Movement, counting_order

_ORDER_RE = re.compile(r"[Ss][Oo]-[0-9]+")
_LINE_RE = re.compile(r"([^*]*)\*([0-9]+)")


@dataclass
class Order:
    id: str
    date: _date
    customer: str
    lines: List[Tuple[str, int]]
    line: int = field(default=0, compare=False, repr=False)

    @property
    def number(self):
        return int(self.id[3:])


def is_order_id(value):
    return _ORDER_RE.fullmatch(value) is not None


def parse_orders(text, catalog):
    """Parse ``orders.txt``; return the orders in file order."""
    orders = []
    seen = {}
    for number, line in content_lines(text):
        parts = split_fields(line)
        if len(parts) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        order_id, date_text, customer, lines_text = parts
        if not is_order_id(order_id):
            raise ParseError(number, "bad order number %r" % order_id)
        order_id = order_id.upper()
        if order_id in seen:
            raise ParseError(
                number, "order %s is already on line %d" % (order_id, seen[order_id])
            )
        when = parse_date(date_text)
        if when is None:
            raise ParseError(number, "bad date %r" % date_text)
        lines = []
        skus = set()
        for item in lines_text.split(","):
            match = _LINE_RE.fullmatch(item)
            if match is None:
                raise ParseError(number, "bad order line %r (SKU*QUANTITY)" % item)
            sku, quantity_text = match.groups()
            if not is_sku(sku) or sku.upper() not in catalog:
