                        "unit": money(line.unit),
                        "gross": money(line.gross),
                        "discount": money(line.discount),
                        "net": money(line.net),
                    }
                    for line in quote.lines
                ],
                "subtotal": money(quote.subtotal),
                "order_discount": money(quote.order_discount),
                "tax": money(quote.tax),
                "total": money(quote.total),
            }
        )
    out = ["%s%s %s %s" % (header_prefix, order.id, order.date.isoformat(), order.customer)]
    for line in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (
                line.sku,
                line.quantity,
                money(line.unit),
                money(line.gross),
                money(line.discount),
                money(line.net),
            )
        )
    out.append("subtotal " + money(quote.subtotal))
    out.append("order discount " + money(quote.order_discount))
    out.append("tax " + money(quote.tax))
    out.append("total " + money(quote.total))
    return lines_out(out)


def cmd_quote(data, request):
    data.orders
    order = data.find_order(request.args[0])
    return _quote_output(order, price_order(order, data.catalog), request)


def _shipped_lines(order, movements):
    return [
