    order = data.find_order(request.args[0])
    lines = _shipped_lines(order, data.movements)
    if not lines:
        raise refused("nothing has shipped yet for order %s" % order.id)
    return _quote_output(order, price_lines(lines, data.catalog), request, "invoice ")


def cmd_fulfil(data, request):
    data.orders
    data.movements
    order = data.find_order(request.args[0])
    if request.date < order.date:
        raise refused(
            "refused: %s is before the date of order %s (%s)"
            % (request.date.isoformat(), order.id, order.date.isoformat())
        )
    plan = plan_fulfilment(order, data.movements, request.date)
    if plan.movements:
        data.append_movements(plan.movements)
    out = ["%s shipped %d backordered %d" % row for row in plan.lines]
    out.append("status " + plan.status)
    return lines_out(out)


def cmd_report(data, request):
    catalog = data.catalog
    orders = data.orders
    movements = data.movements
    rows = []
    for order in sorted(orders, key=lambda o: (o.date, o.number, o.id)):
        progress = shipped_quantities(order, movements)
        shipped_lines = [(sku, s) for sku, _, s in progress if s > 0]
        invoiced = price_lines(shipped_lines, catalog).total if shipped_lines else 0
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": order_status(progress),
                "ordered": sum(q for _, q, _ in progress),
                "shipped": sum(s for _, _, s in progress),
                "quoted": money(price_order(order, catalog).total),
                "invoiced": money(invoiced) if shipped_lines else "0.00",
            }
        )
    if request.format == "json":
        return dump_json(rows)
    if request.format == "csv":
        buffer = io.StringIO()
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(keys)
        for r in rows:
            writer.writerow([r[k] for k in keys])
        return buffer.getvalue()
    return lines_out(
        "%s %s %s %s %d/%d %s %s"
        % (
            r["order"],
            r["date"],
            r["customer"],
            r["status"],
            r["shipped"],
            r["ordered"],
            r["quoted"],
            r["invoiced"],
        )
        for r in rows
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_receive,
    "ship": cmd_ship,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


# ------------------------------------------------------------------- main


def _write(stream, text, errors):
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        stream.flush()
        buffer.write(text.encode("utf-8", errors))
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _silence_stdout():
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def run(argv):
    """Run the command; return ``(status, stdout text, stderr text)``."""
    if argv and argv[0] in ("-h", "--help"):
        return 0, USAGE, ""
    try:
        request = parse_command_line(argv)
        data = Data(request.directory)
        output = HANDLERS[request.command](data, request)
    except Failure as failure:
        return failure.status, "", "stockroom: %s\n" % failure.message
    return 0, output, ""


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    status, out, err = run(list(argv))
    if err:
        try:
            _write(sys.stderr, err, "backslashreplace")
        except (BrokenPipeError, OSError):
            pass
    if out:
        try:
            _write(sys.stdout, out, "surrogateescape")
        except BrokenPipeError:
            _silence_stdout()
    return status

