            text += " " + r["note"]
        out.append(text)
    return lines_out(out)


def _add_movement(data, request, sign):
    date_text, sku, quantity_text = request.args[:3]
    note = request.args[3] if len(request.args) > 3 else ""
    data.movements  # read and check the files first
    product = data.find_product(sku)
    if not quantity_text.isascii() or not quantity_text.isdigit() or int(quantity_text) < 1:
        raise refused(
            "bad quantity %r: it must be a whole number of 1 or more, with no sign"
            % quantity_text
        )
    if "\n" in note or "\r" in note:
        raise refused("a note may not contain a line break")
    note = note.strip(BLANKS)
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise refused("the note is not valid text")
    move = Movement(request.date, product.sku, sign * int(quantity_text), note)
    problem = first_negative(data.movements + [move])
    if problem is not None:
        bad, balance = problem
        where = "this movement" if bad is move else "the movement on line %d of %s" % (
            bad.line,
            MOVEMENTS,
        )
        raise refused(
            "refused: the stock of %s would go below zero (%d) at %s dated %s"
            % (bad.sku, balance, where, bad.date.isoformat())
