                line.quantity,
                money(line.unit),
                money(line.gross),
                money(line.discount),
                money(line.net),
            )
        )
    out.append("subtotal " + money(quote.subtotal))
    out.append("order discount " + money(quote.order_discount))
    out.append("tax " + money(quote.tax))
    out.append("total " + money(quote.total))
    return lines_out(out)


def cmd_quote(data, request):
    data.orders
    order = data.find_order(request.args[0])
    return _quote_output(order, price_order(order, data.catalog), request)


def _shipped_lines(order, movements):
    return [
        (sku, shipped)
        for sku, _, shipped in shipped_quantities(order, movements)
        if shipped > 0
    ]


def cmd_invoice(data, request):
    data.orders
    data.movements
    order = data.find_order(request.args[0])
    lines = _shipped_lines(order, data.movements)
    if not lines:
