            r["date"],
            r["customer"],
            r["status"],
            r["shipped"],
            r["ordered"],
            r["quoted"],
            r["invoiced"],
        )
        for r in rows
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_receive,
    "ship": cmd_ship,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


# ------------------------------------------------------------------- main


def _write(stream, text, errors):
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        stream.flush()
        buffer.write(text.encode("utf-8", errors))
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _silence_stdout():
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def run(argv):
    """Run the command; return ``(status, stdout text, stderr text)``."""
    if argv and argv[0] in ("-h", "--help"):
        return 0, USAGE, ""
    try:
        request = parse_command_line(argv)
        data = Data(request.directory)
        output = HANDLERS[request.command](data, request)
    except Failure as failure:
        return failure.status, "", "stockroom: %s\n" % failure.message
    return 0, output, ""


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    status, out, err = run(list(argv))
    if err:
        try:
            _write(sys.stderr, err, "backslashreplace")
        except (BrokenPipeError, OSError):
            pass
    if out:
        try:
            _write(sys.stdout, out, "surrogateescape")
        except BrokenPipeError:
            _silence_stdout()
    return status

