"""The ``stockroom`` command."""

import csv
import io
import json
import os
import sys

from ._text import BLANKS, ParseError, parse_date
from .orders import (
    order_status,
    parse_orders,
    plan_fulfilment,
    price_lines,
    price_order,
    shipped_quantities,
)
from .shelves import (
    Movement,
    first_negative,
    format_delta,
    format_movement,
    history,
    parse_catalog,
    parse_movements,
    stock_levels,
    stock_status,
    to_buy,
)

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGS]

the shelves:
  stock [--json]                      what is on the shelves
  low [--json]                        what needs buying
  history SKU [--json]                movements of one product
  receive DATE SKU QUANTITY [NOTE]    add a stock-in movement
  ship DATE SKU QUANTITY [NOTE]       add a stock-out movement

the orders:
  quote ORDER [--json]                price an order
  fulfil ORDER DATE                   ship what the shelves can cover
  invoice ORDER [--json]              price what has shipped
  report [--format text|csv|json]     one row per order
"""

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

# command -> (min positionals, max positionals, options, raw)
COMMANDS = {
    "stock": (0, 0, ("--json",), False),
    "low": (0, 0, ("--json",), False),
    "history": (1, 1, ("--json",), False),
    "quote": (1, 1, ("--json",), False),
    "invoice": (1, 1, ("--json",), False),
    "report": (0, 0, ("--format",), False),
    "receive": (3, 4, (), True),
    "ship": (3, 4, (), True),
    "fulfil": (2, 2, (), True),
}

FORMATS = ("text", "csv", "json")


class Failure(Exception):
    """Ends the command with a message on stderr and an exit status."""

    def __init__(self, status, message):
        super().__init__(message)
        self.status = status
        self.message = message


def usage_error(message):
    return Failure(2, message + "\n(run 'stockroom --help' for usage)")


def refused(message):
    return Failure(1, message)


# ------------------------------------------------------------ command line


class Request:
    def __init__(self):
        self.directory = "."
        self.command = None
        self.args = []
        self.json = False
        self.format = "text"


def parse_command_line(argv):
    request = Request()
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise usage_error("--dir needs a folder")
            request.directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            request.directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1

    if not rest:
        raise usage_error("no command given")

    # Options may come before the command name as well as after it.
    before = []
    i = 0
    while i < len(rest) and rest[i].startswith("-") and rest[i] != "-":
        before.append(rest[i])
        if rest[i] == "--format" and i + 1 < len(rest):
            before.append(rest[i + 1])
            i += 1
        i += 1
    if i >= len(rest):
        raise usage_error("no command given")
    command = rest[i]
    if command not in COMMANDS:
        raise usage_error("unknown command %r" % command)
    low, high, options, raw = COMMANDS[command]
    request.command = command

    if raw:
        if before:
            raise usage_error("unknown option %r for %s" % (before[0], command))
        positionals = rest[i + 1:]
    else:
        positionals = []
        words = before + rest[i + 1:]
        j = 0
        while j < len(words):
            word = words[j]
            if word == "--json" and "--json" in options:
                request.json = True
            elif word == "--format" and "--format" in options:
                if j + 1 >= len(words):
                    raise usage_error("--format needs a value (text, csv or json)")
                request.format = words[j + 1]
                j += 1
            elif word.startswith("--format=") and "--format" in options:
                request.format = word[len("--format="):]
            elif word.startswith("-") and word != "-":
                raise usage_error("unknown option %r for %s" % (word, command))
            else:
                positionals.append(word)
            j += 1
        if request.format not in FORMATS:
            raise usage_error(
                "bad --format %r (text, csv or json)" % request.format
            )

    if not low <= len(positionals) <= high:
        if low == high:
            wanted = "%d argument%s" % (low, "" if low == 1 else "s")
        else:
            wanted = "%d to %d arguments" % (low, high)
        raise usage_error(
            "%s takes %s, got %d" % (command, wanted, len(positionals))
        )
    request.args = positionals

    # Dates are checked with the command line.
    date_index = {"receive": 0, "ship": 0, "fulfil": 1}.get(command)
    if date_index is not None:
        text = positionals[date_index]
        when = parse_date(text)
        if when is None:
            raise usage_error("bad date %r (YYYY-MM-DD)" % text)
        request.date = when
    return request


# ------------------------------------------------------------------ files


class Data:
    """Reads the data files from one folder, each at most once."""

    def __init__(self, directory):
        self.directory = directory
        if not os.path.isdir(directory):
            raise Failure(2, "%s: no such folder" % directory)
        self._catalog = None
        self._movements = None
        self._orders = None

    def path(self, name):
        return os.path.join(self.directory, name)

    def read(self, name, required=False):
        path = self.path(name)
        try:
            with open(path, "rb") as handle:
                raw = handle.read()
        except FileNotFoundError:
            if required:
                raise Failure(2, "%s: file not found" % path)
            return ""
        except OSError as error:
            raise Failure(2, "%s: cannot read: %s" % (path, error.strerror or error))
        try:
            return raw.decode("utf-8")
        except UnicodeDecodeError as error:
            line = raw[: error.start].count(b"\n") + 1
            raise Failure(2, "%s: line %d: not valid UTF-8" % (name, line))

    def _parse(self, name, parser, *args):
        text = self.read(name, required=(name == CATALOG))
        try:
            return parser(text, *args)
        except ParseError as error:
            raise Failure(1, "%s: %s" % (name, error))

    @property
    def catalog(self):
        if self._catalog is None:
            self._catalog = self._parse(CATALOG, parse_catalog)
        return self._catalog

    @property
    def movements(self):
        if self._movements is None:
            self._movements = self._parse(MOVEMENTS, parse_movements, self.catalog)
        return self._movements

    @property
    def orders(self):
        if self._orders is None:
            self._orders = self._parse(ORDERS, parse_orders, self.catalog)
        return self._orders

    def append_movements(self, moves):
        path = self.path(MOVEMENTS)
        try:
            with open(path, "rb") as handle:
                existing = handle.read()
        except FileNotFoundError:
            existing = b""
        except OSError as error:
            raise Failure(2, "%s: cannot read: %s" % (path, error.strerror or error))
        data = b""
        if existing and not existing.endswith(b"\n"):
            data += b"\n"
        for move in moves:
            data += format_movement(move).encode("utf-8") + b"\n"
        try:
            with open(path, "ab") as handle:
                handle.write(data)
        except OSError as error:
            raise Failure(2, "%s: cannot write: %s" % (path, error.strerror or error))

    def find_product(self, sku):
        product = self.catalog.get(sku.upper())
        if product is None:
            raise refused("unknown SKU %r: it is not in %s" % (sku, CATALOG))
        return product

    def find_order(self, order_id):
        for order in self.orders:
            if order.id == order_id.upper():
                return order
        raise refused("unknown order %r: it is not in %s" % (order_id, ORDERS))


